  const SESSION_KEY = "insightpatrol_session";
  const LANG_KEY = "insightpatrol_lang";

  let session = null;
  let uiLang = localStorage.getItem(LANG_KEY) || "en";
  let lastResult = null;
  let lastQuery = "Show cyber crime trends in Bengaluru in last 6 months";
  let desk = { roster: [], status_options: [], assignments: [], updates: [], attachments: [] };
  let patrol = { beats: [], duties: [], logs: [], officers: [] };
  let trendChart = null;

  let mapZoom = localStorage.getItem("insightpatrol_map_zoom") || "state";
  let lastMapStations = [];

  /** PS / city pins used on the Karnataka outline map */
